        $latest=$rows[0]??null;if($latest){$file=$this->config['backup'].'/'.basename((string)$latest['filename']);$age=time()-strtotime((string)$latest['created_at']);$this->add('backup','file','File/usia backup terbaru',!is_file($file)?'critical':($age>7*86400?'warning':'pass'),4,'File dicek berdasarkan nama dari registry backup.','Periksa jadwal/retensi.',['exists'=>is_file($file),'bytes'=>is_file($file)?filesize($file):null,'age_days'=>round($age/86400,1)]);$this->deep('backup','archive','Integritas arsip backup terbaru',5,function()use($file){if(preg_match('/\.sql(?:\.gz)?$/i',$file)){if(!is_file($file))throw new RuntimeException('File backup tidak ada');$gzip=str_ends_with(strtolower($file),'.gz');$f=$gzip?gzopen($file,'rb'):fopen($file,'rb');if(!$f)throw new RuntimeException('Backup tidak terbaca');$bytes=0;while(!($gzip?gzeof($f):feof($f))){if($this->expired()||$bytes>536870912)throw new RuntimeException('Batas pemeriksaan dump');$chunk=$gzip?gzread($f,65536):fread($f,65536);if($chunk===false)throw new RuntimeException('Dump rusak');$bytes+=strlen($chunk);}if($gzip)gzclose($f);else fclose($f);$this->add('backup','archive','Integritas arsip backup terbaru','warning',5,'Dump SQL/gzip dapat dibaca; kelengkapan dan restore belum dibuktikan.','Uji pemulihan pada dummy.',['expanded_bytes'=>$bytes]);return;}$z=new ZipArchive();if($z->open($file,ZipArchive::CHECKCONS)!==true)throw new RuntimeException('Arsip rusak');$entries=$z->numFiles;$bad=0;for($i=0;$i<$entries;$i++){if($this->expired())throw new RuntimeException('Deadline');$s=$z->statIndex($i);if(str_ends_with($s['name'],'/'))continue;$stream=$z->getStream($s['name']);if(!$stream){$bad++;continue;}$hash=hash_init('crc32b');$sha=hash_init('sha256');$expanded=0;while(!feof($stream)){if($this->expired()||$expanded>134217728)throw new RuntimeException('Batas waktu/ukuran arsip');$chunk=fread($stream,65536);if($chunk===false)throw new RuntimeException('Stream arsip rusak');$expanded+=strlen($chunk);hash_update($has