    private function sourceUpdates():void {
        $history=[];foreach(glob($this->config['system'].'/history/*.json')?:[] as $f){try{$r=json_decode(file_get_contents($f),true,512,JSON_THROW_ON_ERROR);$history[]=$r;}catch(Throwable $e){$this->add('update','journal-'.basename($f),'Jurnal update rusak','critical',3,'Jurnal JSON tidak dapat dibaca.','Amankan salinan jurnal dan telusuri gangguan disk.');}}usort($history,fn($a,$b)=>strcmp($b['id'],$a['id']));$source=null;$pending=0;
        foreach($history as $r){if(!$source&&($r['kind']??'')==='source_backup'&&($r['status']??'')==='success')$source=$r;if(in_array($r['status']??'',['processing','recovery_required'],true))$pending++;if(in_array($r['kind']??'',['update','restore'],true)&&isset($r['source_snapshot'])){$linked=is_file($this->config['system'].'/archives/'.basename((string)($r['source_snapshot']['file']??'')))&&is_file($this->config['backup'].'/'.basename((string)($r['database_snapshot']['file']??'')))&&!empty($r['database_snapshot']['complete'])&&($r['database_snapshot']['update_id']??'')===$r['id']&&($r['source_snapshot']['update_id']??'')===$r['id'];$this->add('update','snapshot-'.$r['id'],'Keterkaitan snapshot update',$linked?'pass':'critical',4,'Pemeriksaan ID dan metadata snapshot pasangan.','Periksa file kedua snapshot sebelum pemulihan.',['update_id'=>$r['id']]);}}
        $failed=array_filter($history,fn($r)=>in_array($r['kind']??'',['update','restore'],true)&&($r['status']??'')==='failed');$this->add('update','failed-history','Update/restore gagal tercatat',$failed?'warning':'pass',4,'Riwayat kegagalan dibedakan dari proses aktif.','Buka log Update Sistem; hasil migrasi yang terputus memerlukan pemeriksaan manual.',['failed_count'=>count($failed)]);
        $this->add('update','pending','Proses update/pemulihan',$pending?'critical':'pass',8,$pending?'Ada proses belum selesai atau memerlukan pemulihan.':'Tidak ada proses tertunda.','Periksa log dan tahapan tiap database.',['pending'=>$pending]);$this->add('update','maintenance','Marker maintenance',is_file($this->config['system'].'/maintenance.json')?'critical':'pass',4,'Status marker dibaca.','Jangan hapus marker tanpa verifikasi.');
        $rescue=is_file($this->config['system'].'/rescue.php')&&is_file($this->config['system'].'/rescue-engine.php');$this->add('update','rescue','Tool pemulihan darurat',$rescue?'warning':'critical',3,$rescue?'File rescue tersedia; kesiapan hosting belum diuji.':'Tool rescue tidak tersedia.','Uji recovery di staging Hostinger.');
        $this->add('source','latest','Backup Source Code terakhir',$source?'pass':'warning',4,$source?'Backup tervalidasi tercatat.':'Belum ada backup berhasil.','Buat backup dan uji restore.');
        if($source){$this->add('source','extraction','Uji ekstraksi/checksum/lint',!empty($source['restore_test'])?'pass':'unavailable',3,!empty($source['restore_test'])?'Uji ekstraksi dan lint tercatat.':'Belum Diuji.','Ekstraksi bukan bukti restore aplikasi penuh.');$restores=array_filter($history,fn($r)=>($r['kind']??'')==='restore'&&($r['status']??'')==='restored'&&($r['verification']['ok']??false)&&($r['zip_sha256']??'')===($source['zip_sha256']??''));$this->add('source','restore','Uji restore backup terbaru',$restores?'warning':'unavailable',5,$restores?'Pemulihan source dan verifikasi worker tercatat; transaksi browser belum diuji.':'Belum Diuji; uji ekstraksi tidak dihitung sebagai restore aplikasi.','Uji restore dan fungsi aplikasi di staging.');$this->deep('source','checksum','Manifest/checksum source ZIP',6,function()use($source){$file=$this->config['system'].'/archives/'.$source['id'].'.zip';if(!is_file($file)||hash_file('sha256',$file)!==($source['zip_sha256']??''))throw new RuntimeException('Checksum arsip berbeda');require_once $this->config['app'].'/includes/system_update.php';$engine=(new ReflectionClass(NaveenaSystemUpdate::class))->newInstanceWithoutConstructor();$engine->app=$this->config['app'];$engine->root=$this->config['system'];$m=$engine->validate($file,'source_backup');$this->add('source','checksum','Manifest/checksum source ZIP','pass',6,'Signature instalasi, daftar file, path dan SHA-256 diverifikasi.','Pastikan versi restore cocok dengan database.',['files'=>count($m['files']),'version'=>$m['version']]);});}
        $release=null;foreach($history as $entry)if(($entry['kind']??'')==='update'&&($entry['status']??'')==='success'&&($entry['to']??'')===$this->config['version']){$release=$entry;break;}
        if(!$release)$this->add('update','live-manifest','Manifest build source aktif','unavailable',3,'Tidak ada manifest update sukses untuk versi aktif.','Nomor versi bukan bukti integritas source.');else $this->deep('update','live-manifest','Manifest build source aktif',3,function()use($release){require_once $this->config['app'].'/includes/system_update.php';$e=(new ReflectionClass(NaveenaSystemUpdate::class))->newInstanceWithoutConstructor();$e->app=$this->config['app'];$e->root=$this->config['system'];$actual=$e->inventory();$expected=$release['manifest']['files']??[];$ok=$actual===$expected;$this->add('update','live-manifest','Manifest build source aktif',$ok?'pass':'critical',3,$ok?'File aktif sesuai manifest update sukses.':'File aktif berbeda dari manifest update sukses.','Telusuri perubahan manual dan checksum release.',['file_count'=>count($actual)]);});
    }
    private function storage(array $references,array $settings):void {
        foreach(['logo_file','member_card_bg_file','pay_qris_file','favicon_file'] as $k)if(!empty($settings[$k]))$references[]=$settings[$k];$used=[];$missing=0;$remote=0;foreach($references as $name){if(preg_match('~^https?://~i',$name)){$remote++;continue;}$rel=ltrim(str_replace('\\','/',$name),'/');if(str_contains($rel,'..')){ $missing++;continue;}$used[$rel]=true;if(!is_file($this->config['uploads'].'/'.$rel))$missing++;}
        $files=0;$bytes=0;$unreferenced=0;$dupes=0;$hashes=[];$complete=true;
        if(is_dir($this->config['uploads']))foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($this->config['uploads'],FilesystemIterator::SKIP_DOTS)) as $f){if($this->expired()){$complete=false;break;}if(!$f->isFile()||$f->isLink())continue;$files++;$bytes+=$f->getSize();$rel=str_replace('\\','/',substr($f->getPathname(),strlen($this->config['uploads'])+1));if(!isset($used[$rel]))$unreferenced++;if($this->mode==='deep'){$h=hash_file('sha256',$f->getPathname());if(isset($hashes[$h]))$dupes++;$hashes[$h]=true;}}
        $this->add('media','references','Referensi media',$missing?'critical':($remote||!$complete?'warning':'pass'),6,'Tidak menampilkan nama pasien atau nama file media.','Periksa media hilang; kandidat tanpa referensi tidak otomatis aman dihapus.',['references'=>count($references),'missing'=>$missing,'remote_not_checked'=>$remote]);
        $this->add('media','inventory','Inventaris uploads',$complete?'warning':'unavailable',3,'Kandidat tanpa referensi mungkin dipakai modul lain; tidak dihapus.','Periksa manual dan tren storage.',['files'=>$files,'bytes'=>$bytes,'unreferenced_candidates'=>$unreferenced,'scan_complete'=>$complete]);
        $this->add('media','duplicates','Duplikat checksum',$this->mode==='deep'&&$complete?'pass':'unavailable',2,$this->mode==='deep'?'Pemindaian checksum media.':'Tidak dijalankan pada mode cepat.','Jangan hapus duplikat tanpa menelusuri referensi.',['duplicates'=>$dupes]);
        $total=0;$count=0;$temporary=0;$scanDone=true;$roots=[];foreach(['storage','uploads','backup','system'] as $key){$path=realpath($this->config[$key]);if(!$path)continue;$norm=strtolower(str_replace('\\','/',$path));$nested=false;foreach($roots as $old)if($norm===$old||str_starts_with($norm,$old.'/'))$nested=true;if($nested)continue;$roots[]=$norm;try{foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($path,FilesystemIterator::SKIP_DOTS)) as $f){if($this->expired()){$scanDone=false;break;}if(!$f->isFile()||$f->isLink())continue;$count++;$total+=$f->getSize();if(preg_match('/\.(tmp|part|log)$/i',$f->getFilename()))$temporary++;}}catch(Throwable $e){$scanDone=false;}}
        $previous=$this->history()[0]??null;$oldBytes=null;if($previous)foreach($previous['checks'] as $c)if($c['id']==='storage-total'&&($c['evidence']['scan_complete']??false))$oldBytes=$c['evidence']['bytes'];
        $this->add('media','storage-total','Total storage/pertumbuhan',$scanDone?'pass':'unavailable',2,'Inventaris folder aktual dibatasi waktu; perubahan ukuran bukan bukti kebocoran/kerusakan.','Periksa kandidat sementara dan pertumbuhan; tidak ada penghapusan otomatis.',['bytes'=>$total,'files'=>$count,'temporary_log_candidates'=>$temporary,'scan_complete'=>$scanDone,'change_bytes'=>$oldBytes===null?null:$total-$oldBytes]);
    }
    public static function backupRoot():string { $custom=trim((string)getenv('NAVEENA_BACKUP_DIR')); if($custom!=='')return $custom; $iso=function_exists('nv_isolated_root')?nv_isolated_root():'';return $iso!==''?$iso.'/backups':BACKUP_DIR; }
    public function audit(string $action,int $operator,array $meta):void {file_put_contents($this->root.'/audit.jsonl',json_encode(['at'=>date(DATE_ATOM),'action'=>$action,'operator_id'=>$operator,'meta'=>$meta]).PHP_EOL,FILE_APPEND|LOCK_EX);}
    public function save(array $r):void {$temp=$this->root.'/'.$r['id'].'.part';$json=json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);if(file_put_contents($temp,$json,LOCK_EX)!==strlen($json)||!rename($temp,$this->root.'/'.$r['id'].'.json'))throw new RuntimeException('Riwayat gagal disimpan.');$keep=$this->retention();$files=glob($this->root.'/????????-??????-????????????.json')?:[];rsort($files);foreach(array_slice($files,$keep) as $f)unlink($f);}
    public function retention():int{$r=is_file($this->root.'/config.json')?json_decode(file_get_contents($this->root.'/config.json'),true):[];return max(15,min(200,(int)($r['keep']??30)));}
    public function setRetention(int $keep):void{if($keep<15||$keep>200)throw new RuntimeException('Retensi 15–200.');file_put_contents($this->root.'/config.json',json_encode(['keep'=>$keep]),LOCK_EX);}
    public function history():array{$rows=[];foreach(glob($this->root.'/????????-??????-????????????.json')?:[] as $f){$r=json_decode(file_get_contents($f),true);if(is_array($r))$rows[]=$r;}usort($rows,fn($a,$b)=>strcmp($b['id'],$a['id']));return $rows;}
    public function read(string $id):array{if(!preg_match('/^\d{8}-\d{6}-[a-f0-9]{12}$/D',$id))throw new RuntimeException('ID tidak sah.');$file=$this->root.'/'.$id.'.json';if(!is_file($file))throw new RuntimeException('Laporan tidak ada.');return json_decode(file_get_contents($file),true,512,JSON_THROW_ON_ERROR);}
    public function codex(array $r):string{$out='Naveena Health '.$r['id'].' | '.$r['mode'].' | '.$r['status'].' | skor '.$r['score'].'/100 | cakupan '.$r['coverage'].'%'."\n".'Perbaiki temuan berikut dengan backup dan pengujian pada salinan. Jangan reset database, mengganti data pasien, atau membuka maintenance tanpa verifikasi.'."\n";foreach($r['checks'] as $c)if($c['status']!=='pass')$out.=$c['category'].' / '.$c['name'].' ['.$c['status'].']: '.$c['detail'].' '.$c['recommendation']."\n";return $out;}
}

